initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic

    // Initialize Inputs (Synchronize to negedge to avoid race with posedge DUT)
    rstn = 0;
    load_val = 8'h00;
    load_en = 0;

    // Wait for system to stabilize
    repeat(5) @(negedge clk);

    // ---------------------------------------------------------
    // Test Case 1: Synchronous Reset Priority
    // ---------------------------------------------------------
    // Assert reset (active low) while load_en is high. 
    // If priority logic is mutated, output might become load_val instead of 0.
    rstn = 0;
    load_en = 1;
    load_val = 8'hFF;
    @(negedge clk);

    // Release Reset
    rstn = 1;
    @(negedge clk);

    // ---------------------------------------------------------
    // Test Case 2: Load Functionality
    // ---------------------------------------------------------
    // Load 0xAA (Alternating 10101010)
    load_en = 1;
    load_val = 8'hAA;
    @(negedge clk);

    // Load 0x55 (Alternating 01010101)
    load_val = 8'h55;
    @(negedge clk);

    // ---------------------------------------------------------
    // Test Case 3: Left Rotate Logic (Walking 1)
    // ---------------------------------------------------------
    // Targets Bit-Level mutations (e.g., op[0] <= op[7] deletion)
    // Load 0x01
    load_val = 8'h01;
    @(negedge clk); 

    // Disable load, enable shift
    load_en = 0;

    // Shift 9 times. 
    // Expected Sequence: 01 -> 02 -> 04 -> 08 -> 10 -> 20 -> 40 -> 80 -> 01 -> 02
    // If it's a logical shift (mutation), it will become 00 after 8 shifts.
    repeat(9) @(negedge clk);

    // ---------------------------------------------------------
    // Test Case 4: Left Rotate Logic (Walking 0)
    // ---------------------------------------------------------
    // Targets inverse bit logic
    // Load 0xFE (11111110)
    load_en = 1;
    load_val = 8'hFE;
    @(negedge clk);

    load_en = 0;
    // Shift 9 times
    // Expected: FE -> FD -> FB -> F7 -> EF -> DF -> BF -> 7F -> FE -> FD
    repeat(9) @(negedge clk);

    // ---------------------------------------------------------
    // Test Case 5: Complex Pattern & Control Flow
    // ---------------------------------------------------------
    // Load 0xA5 (10100101)
    load_en = 1;
    load_val = 8'hA5;
    @(negedge clk);

    load_en = 0;
    // Shift 1: 01001011 (0x4B)
    @(negedge clk);
    // Shift 2: 10010110 (0x96)
    @(negedge clk);

    // ---------------------------------------------------------
    // Test Case 6: Boundary Values
    // ---------------------------------------------------------
    // All 0s
    load_en = 1;
    load_val = 8'h00;
    @(negedge clk);
    load_en = 0;
    @(negedge clk); // Should remain 00

    // All 1s
    load_en = 1;
    load_val = 8'hFF;
    @(negedge clk);
    load_en = 0;
    @(negedge clk); // Should remain FF

    // 4. Cleanup/Handover
    llm_go_signal = 0;
end
// ============================================


